def clean(df):
    d = df.copy()
    for col in ['penguin_id', 'species', 'island', 'sex']:
        if col in d.columns:
            d[col] = d[col].astype('string').str.strip()
    if 'sex' in d.columns:
        d['sex'] = d['sex'].str.lower()
        d.loc[d['sex'].isin(['', 'nan', 'none']), 'sex'] = pd.NA
    for col in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        if col in d.columns:
            d[col] = pd.to_numeric(d[col], errors='coerce')
    if 'flipper_length_mm' in d.columns:
        neg = d['flipper_length_mm'] < 0
        d.loc[neg, 'flipper_length_mm'] = d.loc[neg, 'flipper_length_mm'].abs()
    if 'body_mass_g' in d.columns:
        mask = d['body_mass_g'] > 6500
        while mask.any():
            d.loc[mask, 'body_mass_g'] = d.loc[mask, 'body_mass_g'] / 1000.0
            mask = d['body_mass_g'] > 6500
    return d

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['species', 'body_mass_g'])
    res = d.groupby('species', dropna=True)['body_mass_g'].mean().sort_index()
    return {str(k): float(v) for k, v in res.items()}
